// One page of the findings the caller can read, in keyset order. sort is severity, detectedAt, package, advisory or status;
// the sort key is (k_num, k_txt, id), compared bytewise, so a cursor means the same on every replica. Each sort and direction
// is a branch that orders by a stored column or by the expression of an index of 00039 and compares the cursor against the
// same expression, so a page reads the first rows of one index in order and stops (Q-VULN-68); a branch whose sort is not
// asked does not run. The advisory's columns are looked up for the rows of the page only.
func (q *Queries) VulnFindingsList(ctx context.Context, arg VulnFindingsListParams) ([]VulnFindingsListRow, error) {
	rows, err := q.db.Query(ctx, vulnFindingsList,
		arg.Descending,
		arg.Whole,
		arg.Rows,
		arg.HasRepos,
		arg.Repos,
		arg.Formats,
		arg.Packages,
		arg.PackagePrefix,
		arg.Versions,
		arg.Ecosystem,
		arg.Advisory,
		arg.Severities,
		arg.Statuses,
		arg.Kind,
		arg.HasKnownExploited,
		arg.KnownExploited,
		arg.HasFixAvailable,
		arg.FixAvailable,
		arg.HasBlocked,
		arg.EnabledRepos,
		arg.MaliciousRepos,
		arg.Blocked,
		arg.BlockReason,
		arg.HasFrom,
		arg.DetectedFrom,
		arg.HasTo,
		arg.DetectedTo,
		arg.Ids,
		arg.Q,
		arg.Sort,
		arg.HasAfter,
		arg.AfterNum,
		arg.AfterID,
		arg.MaxRows,
		arg.AfterTxt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VulnFindingsListRow{}
	for rows.Next() {
		var i VulnFindingsListRow
		if err := rows.Scan(
			&i.ID,
			&i.RepoKey,
			&i.Format,
			&i.Ecosystem,
			&i.PackageName,
			&i.Version,
			&i.AdvisoryID,
			&i.Kind,
			&i.Severity,
			&i.CvssScore,
			&i.KnownExploited,
			&i.FixAvailable,
			&i.FixedVersions,
			&i.Status,
			&i.DismissalReason,
			&i.ResolvedReason,
			&i.Comment,
			&i.Revision,
			&i.DetectedAt,
			&i.ResolvedAt,
			&i.StatusChangedAt,
			&i.StatusChangedBy,
			&i.StatusChangedByName,
			&i.KNum,
			&i.KTxt,
			&i.Summary,
			&i.CvssVersion,
			&i.CvssVector,
			&i.KevAdded,
			&i.Aliases,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

