const vulnScopeCandidates = `-- name: VulnScopeCandidates :many

SELECT r.key AS repo_key, f.package_name AS name, f.version AS version
  FROM vuln_finding f
  JOIN repositories r ON r.id = f.repo_id
 WHERE r.key = ANY($1::text[])
   AND (cardinality($2::text[]) = 0 OR r.format = ANY($2::text[]))
   AND (cardinality($3::text[]) = 0 OR f.package_name = ANY($3::text[])
          OR (f.ecosystem = 'NuGet' AND f.package_name = ANY(SELECT lower(x) FROM unnest($3::text[]) AS x)))
   AND ($4::text = '' OR starts_with(f.package_name, lower($4::text)))
   AND (cardinality($5::text[]) = 0 OR f.version = ANY($5::text[]))
   AND (cardinality($6::text[]) = 0 OR f.id::text = ANY($6::text[]))
   AND ((cardinality($7::text[]) = 0 AND f.status <> 'resolved') OR f.status = ANY($7::text[]))
 LIMIT $8::int
`

type VulnScopeCandidatesParams struct {
	Keys          []string
	Formats       []string
	Packages      []string
	PackagePrefix string
	Versions      []string
	Ids           []string
	Statuses      []string
	MaxRows       int32
}

type VulnScopeCandidatesRow struct {
	RepoKey string
	Name    string
	Version string
}

// Statements of the vulnerability scanning, work package api (docs/developer/vulnerabilities.md). One file per work package;
// every statement of this file is the package's. Plain Go types only (no pgtype): COALESCE nullable columns.
//
// The caller's right is passed in as data, as in package_view.sql (R-VULN-019):
//
//	whole   keys of the repositories whose every finding the caller may read (authz.ReadAll);
//	rows    one entry "<repository key>\x1f<package name>\x1f<version>" per version the caller may read in the other
//	        repositories, decided by the decision point row by row (authz.ReadRows).
//
// A repository in neither list contributes no row. The filters narrow what a request asks about and never widen it.
// The policy of the repositories (R-VULN-015) is passed in as data too: enabled_repos are the keys whose scanning is on, and
// malicious_repos those that also block the malicious findings; the block of a finding is computed by the one rule of
// vuln.Policy.BlockReasonOf, which the Go side applies to every row it returns (vuln.Verdict) and these statements mirror
// only to filter and count.
// The (repository, package, version) triple of every finding of the given repositories, for the repositories whose rows the
// decision point decides one by one; the request's filters narrow them. A triple repeats for each finding of the version, and
// the caller decides it once: sorting the triples apart in SQL would cost more than the repeat. At most max_rows findings; the
// caller asks for one more than it accepts.
func (q *Queries) VulnScopeCandidates(ctx context.Context, arg VulnScopeCandidatesParams) ([]VulnScopeCandidatesRow, error) {
	rows, err := q.db.Query(ctx, vulnScopeCandidates,
		arg.Keys,
		arg.Formats,
		arg.Packages,
		arg.PackagePrefix,
		arg.Versions,
		arg.Ids,
		arg.Statuses,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VulnScopeCandidatesRow{}
	for rows.Next() {
		var i VulnScopeCandidatesRow
		if err := rows.Scan(&i.RepoKey, &i.Name, &i.Version); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

